// One item per Google Maps query. The backend already built the queries
// ("dentist in Brooklyn, New York") and the API parameters; this node only
// drops the empty ones so they are not sent as blank strings.
const MAX_QUERIES = 5; // each query is a billed API call

const hook = $input.first().json;
const body = hook.body || hook;
const search = body.local_search || {};

if (body.search_type && body.search_type !== 'local') {
  throw new Error(`LeadPilot Error: this workflow handles local searches, got "${body.search_type}".`);
}

const queries = (Array.isArray(search.queries) && search.queries.length ? search.queries : [search.query])
  .filter(q => typeof q === 'string' && q.trim())
  .slice(0, MAX_QUERIES);

if (!queries.length) {
  throw new Error('LeadPilot Error: the job carried no local_search query.');
}

const base = {
  limit: search.limit || 20,
  region: search.region,
  language: search.language || 'en',
  business_status: search.business_status || 'OPEN',
  subtypes: search.subtypes,
  extract_emails_and_contacts: search.extract_emails_and_contacts === true ? 'true' : undefined,
};

return queries.map(query => {
  const params = { query, ...base };
  for (const key of Object.keys(params)) {
    if (params[key] === null || params[key] === undefined || params[key] === '') delete params[key];
  }
  return { json: { query, params } };
});

// Turns the raw Google Maps listings into leads:
//   1. de-duplicate across queries
//   2. apply the user's rating / review window (only when they set one)
//   3. keep ONLY listings with a phone number -- that is what makes a lead
// A website is a bonus: those listings are enriched further down.
const MAX_LEADS = 100;

const hook = $('Webhook1').first().json;
const body = hook.body || hook;
const filters = body.filters || {};

const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const minRating = num(filters.min_rating);
const maxRating = num(filters.max_rating);
const minReviews = num(filters.min_reviews);
const maxReviews = num(filters.max_reviews);
const ratingOn = minRating !== null || maxRating !== null;
const reviewsOn = minReviews !== null || maxReviews !== null;

// Optional: better phone normalisation when the library is allowed on this instance.
let parsePhone = null;
try {
  const lib = require('libphonenumber-js');
  parsePhone = lib.parsePhoneNumberFromString || (lib.default && lib.default.parsePhoneNumberFromString) || null;
} catch (e) {}

function cleanPhone(raw, country) {
  if (!raw) return null;
  const text = String(raw).trim();
  if (parsePhone) {
    try {
      const parsed = parsePhone(text, (country || 'US').toUpperCase());
      if (parsed && parsed.isValid()) return parsed.number.replace('+', '');
    } catch (e) {}
  }
  let digits = text.replace(/[^0-9]/g, '');
  if (!text.startsWith('+') && digits.length === 10 && ['US', 'CA', ''].includes((country || '').toUpperCase())) {
    digits = '1' + digits;
  }
  return digits.length >= 7 ? digits : null;
}

// A "website" on one of these hosts is a profile page, not a company domain:
// worth keeping as a link, useless for decision-maker lookup.
const NOT_A_COMPANY_DOMAIN = [
  'facebook.com', 'instagram.com', 'twitter.com', 'x.com', 'linkedin.com', 'tiktok.com', 'youtube.com',
  'yelp.com', 'google.com', 'goo.gl', 'linktr.ee', 'wa.me', 'whatsapp.com', 'booking.com', 'tripadvisor.com',
  'business.site', 'wixsite.com', 'wordpress.com', 'blogspot.com', 'square.site', 'godaddysites.com',
  'doordash.com', 'ubereats.com', 'grubhub.com', 'opentable.com', 'yellowpages.com', 'foursquare.com',
];

function domainOf(url) {
  if (!url) return '';
  return String(url).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[/?#]/)[0].toLowerCase();
}

let raw = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json.data)) raw = raw.concat(item.json.data);
}

const seenIds = new Set();
const seenPhones = new Set();
const leads = [];
let afterWindow = 0;

for (const b of raw) {
  const id = b.business_id || b.place_id || b.google_id || `${b.name}|${b.full_address}`;
  if (seenIds.has(id)) continue;
  seenIds.add(id);

  const rating = num(b.rating);
  const reviews = num(b.review_count) || 0;

  if (ratingOn) {
    if (rating === null) continue; // unrated cannot satisfy a rating window
    if (minRating !== null && rating < minRating) continue;
    if (maxRating !== null && rating > maxRating) continue;
  }
  if (reviewsOn) {
    if (minReviews !== null && reviews < minReviews) continue;
    if (maxReviews !== null && reviews > maxReviews) continue;
  }
  afterWindow++;

  const phone = b.phone_number || (b.emails_and_contacts && (b.emails_and_contacts.phone_numbers || [])[0]) || '';
  const clean = cleanPhone(phone, b.country);
  if (!clean) continue; // no phone, no lead
  if (seenPhones.has(clean)) continue; // same line listed twice (branches, duplicates)
  seenPhones.add(clean);

  const contacts = b.emails_and_contacts || {};
  const emails = (Array.isArray(contacts.emails) ? contacts.emails : [])
    .filter(e => typeof e === 'string' && e.includes('@'))
    .slice(0, 5);
  const socials = {};
  for (const key of ['facebook', 'instagram', 'linkedin', 'twitter', 'youtube', 'tiktok', 'yelp']) {
    if (contacts[key]) socials[key] = contacts[key];
  }

  const domain = domainOf(b.website);
  const enrichable = Boolean(domain) && !NOT_A_COMPANY_DOMAIN.some(d => domain === d || domain.endsWith('.' + d));

  leads.push({
    business_id: id,
    name: b.name || 'Unnamed business',
    phone: String(phone).trim(),
    clean_phone: clean,
    website: b.website || null,
    domain: enrichable ? domain : '',
    enrichable,
    full_address: b.full_address || b.address || null,
    city: b.city || null,
    state: b.state || null,
    country: b.country || null,
    type: b.type || (Array.isArray(b.subtypes) ? b.subtypes[0] : null) || null,
    subtypes: Array.isArray(b.subtypes) ? b.subtypes : [],
    rating,
    review_count: reviews,
    place_link: b.place_link || null,
    verified: b.verified === true,
    latitude: b.latitude ?? null,
    longitude: b.longitude ?? null,
    emails,
    socials,
  });
}

// Website first (the "plus point"), then the better-reviewed.
leads.sort((a, b) => Number(Boolean(b.website)) - Number(Boolean(a.website)) || b.review_count - a.review_count);
const kept = leads.slice(0, MAX_LEADS);

const stats = { raw_count: raw.length, after_window: afterWindow, lead_count: kept.length };

if (!kept.length) {
  // Code nodes that return nothing stop the workflow silently; hand the IF
  // node something to route to the failure report instead.
  return [{ json: { _no_leads: true, ...stats } }];
}

return kept.map(lead => ({ json: { ...lead, ...stats } }));

// Which leads are worth a Snov.io lookup: a real company domain, once each.
// Capped, because every domain costs Snov.io credits and ~30s of waiting.
const MAX_ENRICH = 20;

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const lead = item.json;
  if (!lead.enrichable || !lead.domain || seen.has(lead.domain)) continue;
  seen.add(lead.domain);
  out.push({ json: { domain: lead.domain, business_id: lead.business_id, name: lead.name } });
  if (out.length >= MAX_ENRICH) break;
}

return out.length ? out : [{ json: { _none: true } }];

// Same idea as the B2B "Filter & Limit Prospects", with two differences:
//  * it never throws -- a local lead is already complete with its phone, so
//    finding no decision maker must not fail the search;
//  * a small business rarely lists a "procurement" title, so owners and
//    managers lead, and if no title matches the first people found are kept.
const MAX_PER_COMPANY = 3;
const MAX_TOTAL = 60;

const roles = ['owner', 'founder', 'ceo', 'president', 'proprietor', 'principal', 'partner', 'director',
  'managing', 'manager', 'head', 'chief', 'vp', 'vice president'];

let total = 0;
const out = [];

for (const item of $input.all()) {
  if (total >= MAX_TOTAL) break;

  const people = Array.isArray(item.json.data) ? item.json.data
    : Array.isArray(item.json.prospects) ? item.json.prospects : [];
  if (!people.length) continue;

  const domain = (item.json.meta && item.json.meta.domain) || '';
  const withEmailLink = people.filter(p => p && p.search_emails_start);
  const matched = withEmailLink.filter(p => {
    const title = String(p.position || p.title || p.job_title || '').toLowerCase();
    return roles.some(role => title.includes(role));
  });

  const chosen = (matched.length ? matched : withEmailLink).slice(0, Math.min(MAX_PER_COMPANY, MAX_TOTAL - total));
  if (!chosen.length) continue;

  total += chosen.length;
  out.push({ json: { ...item.json, data: chosen.map(p => ({ ...p, lp_domain: domain })) } });
}

return out.length ? out : [{ json: { _none: true } }];

// One item per distinct phone number: what the WhatsApp check runs on, so a
// number shared by two listings is only paid for once.
const leads = $('Filter & Keep Phone Leads').all().map(i => i.json);

let snovEmails = 0;
try {
  for (const item of $('Collect Emails').all()) {
    const d = item.json.data;
    if (Array.isArray(d)) {
      if (d[0] && d[0].email) snovEmails++;
    } else if (d && Array.isArray(d.emails) && d.emails[0] && d.emails[0].smtp_status === 'valid') {
      snovEmails++;
    }
  }
} catch (e) {}

const siteEmails = leads.reduce((n, lead) => n + (lead.emails || []).length, 0);
const contactCount = snovEmails + siteEmails;

const seen = new Set();
const out = [];
for (const lead of leads) {
  if (!lead.clean_phone || seen.has(lead.clean_phone)) continue;
  seen.add(lead.clean_phone);
  out.push({ json: { clean_phone: lead.clean_phone, contact_count: contactCount } });
}

return out;

// Assembles the results the backend expects: one company per Google Maps
// lead, with its contacts. Reads the earlier nodes by name, each inside a
// try/catch, because on a run with no websites (or no WhatsApp check) those
// nodes never executed.
const hook = $('Webhook1').first().json;
const body = hook.body || hook;
const whatsappOn = body.validate_whatsapp === true;

const leads = $('Filter & Keep Phone Leads').all().map(i => i.json).filter(l => !l._no_leads);

const last10 = phone => {
  const digits = String(phone || '').replace(/[^0-9]/g, '');
  return digits.length >= 10 ? digits.slice(-10) : digits;
};
const domainOf = email => (String(email || '').includes('@') ? String(email).split('@')[1].toLowerCase() : '');
const nameKey = (first, last) => `${String(first || '').trim().toLowerCase()}_${String(last || '').trim().toLowerCase()}`;

// --- 1. WhatsApp status per phone -------------------------------------------
// Read from THIS node's input rather than from the validator node by name:
// when the check ran, the validator's output is exactly what arrives here, so
// renaming or recreating that node can never break the lookup again. When the
// check was skipped, the input is the phone list, which carries no status.
//
// The validator answers one row per number: { phone_number, status: "valid" |
// "invalid" }. "valid" = the number is on WhatsApp. A row with no recognisable
// status (an API error, a timeout) leaves that number unchecked (null), so it
// is neither shown as reachable nor billed as a check.
const POSITIVE = ['valid', 'exists', 'active', 'true', 'yes', 'registered'];
const NEGATIVE = ['invalid', 'not active', 'inactive', 'not found', 'false', 'no', 'not registered'];

const whatsapp = {};
if (whatsappOn) {
  const rows = $input.all();
  let phones = [];
  try { phones = $('Unique Phones').all(); } catch (e) {}

  rows.forEach((res, index) => {
    let row = res.json || {};
    // Some responses wrap the rows in an array property.
    const nested = Object.values(row).find(v => Array.isArray(v) && v.length && typeof v[0] === 'object');
    if (nested) row = nested[0];

    let verdict = null;
    if (row.exists === true || row.has_whatsapp === true) verdict = 'Active';
    else if (row.exists === false || row.has_whatsapp === false) verdict = 'Not Active';
    else {
      const status = String(row.status ?? row.whatsapp_status ?? '').trim().toLowerCase();
      if (POSITIVE.includes(status)) verdict = 'Active';
      else if (NEGATIVE.includes(status)) verdict = 'Not Active';
    }
    if (verdict === null) return; // not a result row, or an error: leave unchecked

    // The row names its own number; the position is only a fallback, and only
    // safe when every number produced exactly one row.
    const phone = row.phone_number || row.phone || row.number
      || (rows.length === phones.length && phones[index] ? phones[index].json.clean_phone : '');
    const key = last10(phone);
    if (key) whatsapp[key] = verdict;
  });
}
const whatsappFor = phone => {
  if (!whatsappOn || !phone) return null;
  const verdict = whatsapp[last10(phone)];
  return verdict === undefined ? null : verdict;
};

// --- 2. Decision makers found through the website (Snov.io) -------------------
const people = {};          // nameKey -> { position, source_page, domain }
try {
  for (const item of $('Limit Prospects').all()) {
    for (const p of Array.isArray(item.json.data) ? item.json.data : []) {
      people[nameKey(p.first_name, p.last_name)] = {
        position: p.position || p.title || null,
        source_page: p.source_page || null,
        domain: p.lp_domain || '',
      };
    }
  }
} catch (e) {}

const byEmail = {};         // email -> prospect record from the email search
try {
  for (const item of $('Get prospect email search result').all()) {
    const d = item.json.data;
    if (!d || Array.isArray(d) || !Array.isArray(d.emails)) continue;
    for (const e of d.emails) if (e && e.email) byEmail[e.email.toLowerCase()] = d;
  }
} catch (e) {}

const makersByDomain = {};
const seenEmails = new Set();
const addMaker = (record, email, status) => {
  if (!email || seenEmails.has(email.toLowerCase())) return;
  const known = people[nameKey(record.first_name, record.last_name)] || {};
  const domain = known.domain || domainOf(email);
  if (!domain) return;
  seenEmails.add(email.toLowerCase());
  (makersByDomain[domain] = makersByDomain[domain] || []).push({
    full_name: `${record.first_name || ''} ${record.last_name || ''}`.trim() || 'Decision Maker',
    job_title: record.position || known.position || null,
    verified_email: email,
    email_status: status,
    linkedin_url: record.linkedin_url || record.source_page || known.source_page || null,
    phone_number: null,
    whatsapp_status: null,
  });
};

try {
  for (const item of $('Collect Emails').all()) {
    const d = item.json.data;
    if (Array.isArray(d)) {
      // Email-verifier result: [{ email, result: { smtp_status } }]
      const row = d[0] || {};
      const status = (row.result && row.result.smtp_status) || row.status;
      if (row.email && status === 'valid') addMaker(byEmail[row.email.toLowerCase()] || {}, row.email, 'valid');
    } else if (d && Array.isArray(d.emails) && d.emails[0]) {
      if (d.emails[0].smtp_status === 'valid') addMaker(d, d.emails[0].email, 'valid');
    }
  }
} catch (e) {}

// --- 3. One company per lead ----------------------------------------------------
const companies = [];
for (const lead of leads) {
  const status = whatsappFor(lead.clean_phone);
  const phone = '+' + lead.clean_phone;

  // The business's own line is the primary contact: it carries the phone,
  // the WhatsApp result, and the first email found on its website.
  const contacts = [{
    full_name: lead.name,
    job_title: 'Main business line',
    verified_email: lead.emails[0] || null,
    email_status: lead.emails[0] ? 'unverified' : null,
    linkedin_url: lead.socials.linkedin || null,
    phone_number: phone,
    whatsapp_status: status,
  }];

  for (const maker of (lead.domain && makersByDomain[lead.domain]) || []) contacts.push(maker);

  companies.push({
    company_name: lead.name,
    website: lead.website,
    location: lead.full_address,
    industry: lead.type,
    company_size: null,
    hq_phone: phone,
    decision_makers: contacts,

    // No column of their own; the backend keeps them with the company.
    source: 'google_maps',
    has_website: Boolean(lead.website),
    rating: lead.rating,
    review_count: lead.review_count,
    place_link: lead.place_link,
    google_verified: lead.verified,
    categories: lead.subtypes,
    city: lead.city,
    state: lead.state,
    country: lead.country,
    latitude: lead.latitude,
    longitude: lead.longitude,
    emails: lead.emails,
    socials: lead.socials,
    whatsapp_status: status,
  });
}

return companies.map(company => ({ json: company }));
